import argparse
import json
from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
CONFIG = ".agent-kit.json"
COPILOT_HEADER = (
    "# GitHub Copilot Instructions\n\n"
    "Auto-generated by scripts/build_agents_md.py.\n"
    "Do not edit manually.\n\n"
)
CROSS_IDE_TARGETS = [
    (".cursorrules", False),
    (".clinerules", False),
    (".github/copilot-instructions.md", True),
]
CLAUDE_INSTRUCTIONS = (
    "# Claude Code Instructions\n\n"
    "<!-- Generated by scripts/build_agents_md.py; do not edit manually. -->\n\n"
    "@AGENTS.md\n"
)


def read_json(path: Path) -> dict:
    """Read a UTF-8 JSON object used as agent-kit configuration.

    Call this for checked-in profile and project configuration files. The
    function rejects non-object roots so callers can rely on named settings.

    Args:
        path: Existing JSON file to read.

    Returns:
        Parsed JSON object.

    Raises:
        ValueError: If the document root is not an object.
        OSError: If the file cannot be read.
        json.JSONDecodeError: If the file is invalid JSON.
    """
    value = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(value, dict):
        raise ValueError(f"Expected a JSON object: {path}")
    return value


def load_settings(root: Path) -> dict:
    """Load and validate the repository's selected profile and context budget.

    Use this before building or checking generated instruction files. Guides
    are stored as names without the `.md` suffix.

    Args:
        root: Agent-kit or installed-project root.

    Returns:
        Normalized settings containing profile, guides, and max_agents_bytes.

    Raises:
        ValueError: If a required setting has the wrong type or value.
    """
    path = root / CONFIG
    settings = read_json(path) if path.exists() else {}
    profile = settings.get("profile", "lean")
    guides = settings.get("guides", [])
    max_agents_bytes = settings.get("max_agents_bytes", 32768)
    if not isinstance(profile, str) or not profile:
        raise ValueError(f"profile must be a non-empty string in {path}")
    if not isinstance(guides, list) or not all(isinstance(item, str) and item for item in guides):
        raise ValueError(f"guides must be a list of names in {path}")
    if not isinstance(max_agents_bytes, int) or max_agents_bytes <= 0:
        raise ValueError(f"max_agents_bytes must be a positive integer in {path}")
    return {
        "profile": profile,
        "guides": list(dict.fromkeys(guides)),
        "max_agents_bytes": max_agents_bytes,
    }


def resolve_profile(root: Path, profile_name: str, stack: tuple[str, ...] = ()) -> list[str]:
    """Resolve a profile and its parent profiles into an ordered rule list.

    Profiles provide progressive disclosure by keeping the default root policy
    small while allowing domain-specific rule sets when a project needs them.

    Args:
        root: Repository root containing `profiles/` and `rules/`.
        profile_name: Profile filename without `.json`.
        stack: Internal recursion trail used to detect inheritance cycles.

    Returns:
        De-duplicated rule directory names in evaluation order.

    Raises:
        ValueError: If a profile is missing, cyclic, malformed, or references a
            rule that does not exist.
    """
    if profile_name in stack:
        raise ValueError(f"Profile inheritance cycle: {' -> '.join((*stack, profile_name))}")
    profile_path = root / "profiles" / f"{profile_name}.json"
    if not profile_path.exists():
        raise ValueError(f"Unknown profile: {profile_name}")
    profile = read_json(profile_path)
    declared = profile.get("rules", [])
    if declared == "all":
        rules = sorted(path.parent.name for path in (root / "rules").glob("*/RULE.md"))
    elif isinstance(declared, list) and all(isinstance(item, str) for item in declared):
        parent = profile.get("extends")
        rules = resolve_profile(root, parent, (*stack, profile_name)) if parent else []
        rules.extend(declared)
    else:
        raise ValueError(f"rules must be a list or 'all': {profile_path}")
    unique_rules = list(dict.fromkeys(rules))
    missing = [name for name in unique_rules if not (root / "rules" / name / "RULE.md").exists()]
    if missing:
        raise ValueError(f"Profile {profile_name} references missing rules: {', '.join(missing)}")
    return unique_rules


def resolve_guides(root: Path, guide_names: list[str]) -> list[Path]:
    """Resolve configured framework guide names to existing Markdown files.

    Args:
        root: Repository root containing `guides/`.
        guide_names: Guide names with or without `.md` suffixes.

    Returns:
        Guide paths in configured order.

    Raises:
        ValueError: If a guide does not exist or attempts path traversal.
    """
    guide_paths = []
    for raw_name in guide_names:
        name = raw_name[:-3] if raw_name.endswith(".md") else raw_name
        if not name.replace("-", "").isalnum():
            raise ValueError(f"Invalid guide name: {raw_name}")
        path = root / "guides" / f"{name}.md"
        if not path.exists():
            raise ValueError(f"Unknown guide: {raw_name}")
        guide_paths.append(path)
    return guide_paths


def build_cheatsheet(rule_files: list[Path]) -> str:
    """Build navigation rows for the rules selected by the active profile.

    Args:
        rule_files: Ordered source rule files included in the generated policy.

    Returns:
        Markdown table with stable anchors and one-line purposes.
    """
    rows = []
    for rule_file in rule_files:
        lines = rule_file.read_text(encoding="utf-8-sig").splitlines()
        name = next((line[2:] for line in lines if line.startswith("# ")), rule_file.parent.name)
        purpose = ""
        for index, line in enumerate(lines):
            if line == "## Purpose":
                purpose = lines[index + 1].strip() if index + 1 < len(lines) else ""
                break
        anchor = "rule-" + rule_file.parent.name
        rows.append(f"| [{name}](#{anchor}) | {purpose} |")
    header = "| Rule | Purpose |\n|------|---------|"
    return header + "\n" + "\n".join(rows)


def build_intro(rule_files: list[Path], profile_name: str, guide_files: list[Path]) -> str:
    """Build the generated document header and active-policy summary.

    Args:
        rule_files: Ordered rules selected for this build.
        profile_name: Active profile recorded for reviewers.
        guide_files: Framework guides appended to the generated instructions.

    Returns:
        Markdown introduction and quick-reference table.
    """
    guide_summary = ", ".join(path.stem for path in guide_files) or "none"
    lines = [
        "# AGENTS.md",
        "",
        "This file is generated. Edit `.agent-kit.json`, `profiles/`, `rules/`, or `guides/`, then rebuild.",
        f"Active profile: `{profile_name}`. Active guides: {guide_summary}.",
        "",
        "## Quick Reference",
        "",
        build_cheatsheet(rule_files),
        "",
        "## Project Adaptation",
        "",
        "- Read only the repository context required for the current task.",
        "- Discover and use the repository's actual package manager and commands.",
        "- Follow verified local architecture, naming, formatting, and test conventions.",
        "- Put framework or subtree-specific guidance in the closest nested `AGENTS.md`.",
        "- Apply `definition-of-done.md` only to applicable implementation work.",
    ]
    return "\n".join(lines)


def build_parts(
    rules_dir: Path,
    rule_names: list[str] | None = None,
    guide_files: list[Path] | None = None,
    profile_name: str = "full",
) -> list[str]:
    """Build generated instruction sections with stable source markers.

    This public helper keeps `rule_names=None` compatible with earlier callers
    by including every rule. Production generation always passes a profile list.

    Args:
        rules_dir: Directory containing one subdirectory per rule.
        rule_names: Optional ordered rule names; all rules when omitted.
        guide_files: Optional framework guide files to append.
        profile_name: Active profile label shown in the introduction.

    Returns:
        Introduction followed by rule and guide Markdown sections.
    """
    if rule_names is None:
        rule_files = sorted(rules_dir.glob("*/RULE.md"))
    else:
        rule_files = [rules_dir / name / "RULE.md" for name in rule_names]
    guides = guide_files or []
    parts = [build_intro(rule_files, profile_name, guides).strip()]
    for rule_file in rule_files:
        source = rule_file.relative_to(rules_dir.parent).as_posix()
        anchor = "rule-" + rule_file.parent.name
        parts.append(
            f'<!-- source: {source} -->\n<a id="{anchor}"></a>\n\n'
            + rule_file.read_text(encoding="utf-8-sig").strip()
        )
    for guide_file in guides:
        source = guide_file.relative_to(rules_dir.parent).as_posix()
        anchor = "guide-" + guide_file.stem
        parts.append(
            f'<!-- source: {source} -->\n<a id="{anchor}"></a>\n\n'
            + guide_file.read_text(encoding="utf-8-sig").strip()
        )
    return parts


def generated_outputs(root: Path, settings: dict) -> dict[Path, str]:
    """Render every generated instruction target without writing to disk.

    Args:
        root: Repository root containing rules, profiles, and guides.
        settings: Normalized settings returned by `load_settings`.

    Returns:
        Mapping from output path to expected UTF-8 text.

    Raises:
        ValueError: If generated `AGENTS.md` exceeds the configured byte budget.
    """
    rule_names = resolve_profile(root, settings["profile"])
    guide_files = resolve_guides(root, settings["guides"])
    parts = build_parts(root / "rules", rule_names, guide_files, settings["profile"])
    agents_content = "\n\n---\n\n".join(parts) + "\n"
    byte_count = len(agents_content.encode("utf-8"))
    if byte_count > settings["max_agents_bytes"]:
        raise ValueError(
            f"Generated AGENTS.md is {byte_count} bytes; "
            f"budget is {settings['max_agents_bytes']} bytes"
        )
    body = "\n\n---\n\n".join(parts[1:]) + "\n"
    outputs = {root / "AGENTS.md": agents_content}
    outputs[root / "CLAUDE.md"] = CLAUDE_INSTRUCTIONS
    for relative_path, include_header in CROSS_IDE_TARGETS:
        outputs[root / relative_path] = (COPILOT_HEADER if include_header else "") + body
    return outputs


def build_manifest(root: Path) -> str:
    """Return a deterministic inventory of distributable repository paths.

    Args:
        root: Repository root to inventory.

    Returns:
        Newline-terminated relative path list excluding Git and cache internals.
    """
    entries = []
    for path in sorted(root.rglob("*"), key=lambda item: item.relative_to(root).as_posix()):
        relative_path = path.relative_to(root)
        if ".git" in relative_path.parts or "__pycache__" in relative_path.parts:
            continue
        relative = relative_path.as_posix() + ("/" if path.is_dir() else "")
        entries.append(relative)
    return "\n".join(entries) + "\n"


def write_config(root: Path, settings: dict) -> None:
    """Persist normalized build settings after an explicit CLI override.

    Args:
        root: Repository root receiving `.agent-kit.json`.
        settings: Normalized settings to serialize.

    Side effects:
        Replaces the agent-kit configuration with formatted UTF-8 JSON.
    """
    content = json.dumps(settings, indent=2, ensure_ascii=False) + "\n"
    (root / CONFIG).write_text(content, encoding="utf-8", newline="\n")


def build_all(root: Path = ROOT, settings: dict | None = None) -> list[Path]:
    """Generate profile-scoped instructions and refresh the path manifest.

    Args:
        root: Repository or installed project root.
        settings: Optional normalized settings; load project config when omitted.

    Returns:
        Paths written by the build.

    Side effects:
        Replaces generated instruction files and `MANIFEST.txt`.
    """
    active_settings = settings or load_settings(root)
    outputs = generated_outputs(root, active_settings)
    for path, content in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
    manifest = root / "MANIFEST.txt"
    manifest.touch(exist_ok=True)
    manifest.write_text(build_manifest(root), encoding="utf-8", newline="\n")
    written = [*outputs, manifest]
    print(
        f"Generated {len(outputs)} instruction files with profile "
        f"{active_settings['profile']} and refreshed MANIFEST.txt."
    )
    return written


def check_generated(root: Path = ROOT, settings: dict | None = None) -> list[str]:
    """Compare generated files with expected profile-scoped content.

    Args:
        root: Repository or installed project root.
        settings: Optional normalized settings; load project config when omitted.

    Returns:
        Human-readable stale-file errors; an empty list means current outputs.
    """
    active_settings = settings or load_settings(root)
    errors = []
    for path, expected in generated_outputs(root, active_settings).items():
        if not path.exists() or path.read_text(encoding="utf-8") != expected:
            errors.append(f"Stale generated file: {path.relative_to(root).as_posix()}")
    return errors


def parse_args(argv: list[str]) -> argparse.Namespace:
    """Parse build, profile-selection, and freshness-check command options.

    Args:
        argv: Command-line arguments excluding the program name.

    Returns:
        Parsed argparse namespace.
    """
    parser = argparse.ArgumentParser(description="Build profile-scoped agent instructions.")
    parser.add_argument("--profile", help="Select and persist a profile from profiles/*.json.")
    parser.add_argument(
        "--guide",
        action="append",
        default=None,
        help="Select and persist a framework guide; repeat for multiple guides.",
    )
    parser.add_argument("--clear-guides", action="store_true", help="Persist an empty guide list.")
    parser.add_argument(
        "--max-agents-bytes",
        type=int,
        help="Select and persist a positive generated AGENTS.md byte budget.",
    )
    parser.add_argument("--check", action="store_true", help="Check freshness without writing files.")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    """Run the configured build or a non-mutating freshness check.

    Args:
        argv: Optional CLI arguments for tests; defaults to `sys.argv[1:]`.

    Returns:
        Process exit code: zero on success, one on configuration or freshness errors.
    """
    args = parse_args(sys.argv[1:] if argv is None else argv)
    try:
        settings = load_settings(ROOT)
        if args.profile:
            settings["profile"] = args.profile
        if args.clear_guides:
            settings["guides"] = []
        elif args.guide is not None:
            settings["guides"] = list(dict.fromkeys(args.guide))
        if args.max_agents_bytes is not None:
            if args.max_agents_bytes <= 0:
                raise ValueError("--max-agents-bytes must be positive")
            settings["max_agents_bytes"] = args.max_agents_bytes
        if args.check:
            if args.profile or args.guide is not None or args.clear_guides or args.max_agents_bytes is not None:
                raise ValueError("--check cannot be combined with configuration changes")
            errors = check_generated(ROOT, settings)
            if errors:
                for error in errors:
                    print(error)
                return 1
            print("Generated instruction files are current and within budget.")
            return 0
        if args.profile or args.guide is not None or args.clear_guides or args.max_agents_bytes is not None:
            resolve_profile(ROOT, settings["profile"])
            resolve_guides(ROOT, settings["guides"])
            write_config(ROOT, settings)
        build_all(ROOT, settings)
        return 0
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"Build failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
